import { Buffer } from 'node:buffer';
import { isIP } from 'node:net';
import {
    parseDkimHeaders,
    formatRelaxedLine,
    stripSignatureValue,
    formatAuthHeaderRow,
    formatSignatureHeaderLine,
    writeToStream,
    validateAlgorithm,
    createError,
    addWarning,
    KEY_ERROR_COMMENTS,
    splitAlgorithm,
    createKeyCache,
    isHostNameDomain
} from '../tools.js';
import { TIMESTAMP, BODY_LENGTH, MAX_ARC_INSTANCE, ARC_HEADER_KEYS } from '../dkim/syntax.js';
import crypto from 'node:crypto';
import { DkimSigner } from '../dkim/dkim-signer.js';
import type { ParsedHeaders } from '../tools.js';
import type {
    ARCChainEntry,
    ARCCreateSealData,
    ARCData,
    ARCOptions,
    ARCResult,
    ARCSealError,
    ARCSealOptions,
    DKIMResult,
    DKIMSignError,
    MessageInput
} from '../types.js';

type KeyCache = ReturnType<typeof createKeyCache>;

// the header fields of an ARC set
type ArcHeaderKey = 'arc-seal' | 'arc-message-signature' | 'arc-authentication-results';

// a header field as parseDkimHeaders() returns it
type ArcHeaderField = ReturnType<typeof parseDkimHeaders>;

// An ARC set while getARChain() collects and checks it
interface ArcSet {
    i: number;
    'arc-seal'?: ArcHeaderField | undefined;
    'arc-message-signature'?: ArcHeaderField | undefined;
    'arc-authentication-results'?: ArcHeaderField | undefined;
}

/**
 * ARC data for arc(), as the DKIM verifier collects it
 */
export interface ARCVerifyData extends ARCData {
    /**
     * What the lenient mode accepted in the chain that the strict mode would have rejected
     */
    warnings?: string[] | undefined;

    /**
     * Key lookups of the DKIM verification, reused when they were made with the same resolver
     */
    keyCache?: KeyCache | undefined;
}

/**
 * Options of getARChain()
 */
export interface GetARChainOptions {
    /**
     * Apply the RFC 8617 and RFC 6376 syntax rules exactly
     */
    strict?: boolean | undefined;

    /**
     * Lax acceptance markers are added here
     */
    warnings?: string[] | undefined;
}

/**
 * Options of verifyASChain()
 */
export interface VerifyASChainOptions extends ARCOptions {
    /**
     * Lax acceptance markers of the key records are added here
     */
    warnings?: string[] | undefined;

    /**
     * A createKeyCache() of the same resolver, shared with other key lookups of the message
     */
    keyCache?: KeyCache | undefined;
}

/**
 * The result of createSeal()
 */
export interface CreateSealResult {
    /**
     * ARC-Seal, ARC-Message-Signature and ARC-Authentication-Results, empty if no set was created
     */
    headers: string[];

    /**
     * Why the set was not created, or why a signature failed
     */
    errors: ARCSealError[];

    /**
     * What the default mode accepted and the strict mode would not
     */
    warnings: string[];

    /**
     * The instance (i=) of a created set
     */
    instance?: number | undefined;
}

// the values signAS() creates the ARC-Seal from
interface ArcSealSignatureData {
    instance?: number | undefined;
    algorithm: string;
    selector: string;
    signingDomain: string;
    bodyHash?: string | null | undefined;
    cv: string;
    signTime?: Date | string | number | undefined;
    privateKey: string | Buffer;
}

// RFC 8617 section 3.9: chain-status = ("none" / "fail" / "pass"). ABNF strings are case-insensitive
const CHAIN_STATUS = ['none', 'pass', 'fail'];

// RFC 8617 section 3.9: position = 1*2DIGIT
const INSTANCE_VALUE = /^[0-9]{1,2}$/;

// RFC 8617 section 4.1.1: arc-info = instance [CFWS] ";" authres-payload, so the instance is the
// first thing in an ARC-Authentication-Results value. Comments (without nesting) are allowed as CFWS
const CFWS = '(?:[ \\t\\r\\n]|\\([^()\\\\]*\\))*';
const AAR_INSTANCE = new RegExp(`^${CFWS}i${CFWS}=${CFWS}([0-9]{1,2})${CFWS};`);

// Tags an ARC-Seal (RFC 8617 section 4.1.3) and an ARC-Message-Signature (section 4.1.2, with
// the DKIM-Signature tags of RFC 6376 section 3.5 except v= and i=) can not do without
const REQUIRED_TAGS = {
    'arc-seal': ['a', 'b', 'cv', 'd', 's'],
    'arc-message-signature': ['a', 'b', 'bh', 'd', 'h', 's']
};

const NUMERIC_TAGS: Record<'arc-seal' | 'arc-message-signature', [string, RegExp][]> = {
    'arc-seal': [['t', TIMESTAMP]],
    'arc-message-signature': [
        ['t', TIMESTAMP],
        ['x', TIMESTAMP],
        ['l', BODY_LENGTH]
    ]
};

const SHORT_NAMES: Record<string, string> = {
    'arc-seal': 'as',
    'arc-message-signature': 'ams',
    'arc-authentication-results': 'aar'
};

// the cv= value of an ARC set in lower case, or an empty string
const getCv = (arcInstance: ARCChainEntry | ArcSet | null | undefined): string =>
    (arcInstance?.['arc-seal']?.parsed?.cv?.value || '').toString().toLowerCase().trim();

// The highest i= found on the ARC header fields of a message, or 0, and the cv= of the seal
// with that instance. A new set follows it (RFC 8617 section 5.1 step 3) even when the chain
// can not be parsed, so that it never reuses an instance that already exists
const getHighestArcInstance = (headers: ParsedHeaders | null | undefined): { highest: number; latestCv: string | false } => {
    let highest = 0;
    let latestCv: string | false = false;
    for (let row of headers?.parsed || []) {
        if (!(ARC_HEADER_KEYS as readonly (string | null)[]).includes(row.key)) {
            continue;
        }
        let parsed;
        try {
            parsed = parseDkimHeaders(row.line)?.parsed;
        } catch {
            continue;
        }
        let instance = parsed?.i?.value;
        if (typeof instance !== 'number' || !Number.isInteger(instance) || instance < 1) {
            continue;
        }
        if (instance > highest) {
            highest = instance;
            latestCv = false;
        }
        if (instance === highest && row.key === 'arc-seal' && typeof parsed?.cv?.value === 'string') {
            latestCv = parsed.cv.value.toLowerCase().trim();
        }
    }
    return { highest, latestCv };
};

// Where a new ARC set goes (RFC 8617 section 5.1 steps 2 and 3): the highest existing instance
// and the cv= of its seal, from the header fields and from the parsed chain, for callers that
// pass the chain without the complete header list
const getArcPosition = (headers: ParsedHeaders | null | undefined, chain: ARCChainEntry[] | null | undefined) => {
    let { highest, latestCv } = getHighestArcInstance(headers);
    let lastEntry = chain?.length ? chain[chain.length - 1] : false;
    if (lastEntry && lastEntry.i >= highest) {
        highest = lastEntry.i;
        latestCv = getCv(lastEntry) || latestCv;
    }
    return { highest, latestCv };
};

// the DNS name of the key record of an ARC-Seal
const sealKeyName = (seal: NonNullable<ARCChainEntry['arc-seal']>): string => `${seal.parsed?.s?.value}._domainkey.${seal.parsed?.d?.value}`;

const verifyAS = async (chain: ARCChainEntry[], opts: VerifyASChainOptions) => {
    const { strict, warnings, keyCache } = opts || {};

    let chunks: Buffer[] = [];
    let signatureHeader!: NonNullable<ARCChainEntry['arc-seal']>;

    for (let i = 0; i < chain.length; i++) {
        let isLast = i === chain.length - 1;
        let link = chain[i];

        chunks.push(formatRelaxedLine(link['arc-authentication-results']!.original, '\r\n'));
        chunks.push(formatRelaxedLine(link['arc-message-signature']!.original, '\r\n'));

        if (!isLast) {
            chunks.push(formatRelaxedLine(link['arc-seal']!.original, '\r\n'));
        } else {
            signatureHeader = link['arc-seal']!;
            if (!signatureHeader.parsed?.s?.value || !signatureHeader.parsed?.d?.value) {
                throw createError(`Invalid ARC-Seal header`, 'invalid_arc_seal');
            }

            chunks.push(stripSignatureValue(formatRelaxedLine(link['arc-seal']!.original), strict));
        }
    }

    // The algorithm is read from the seal itself. Every seal of the chain is verified here, not
    // only the newest one, so nothing set up elsewhere for the newest seal can be relied on
    let algorithm = (signatureHeader.parsed?.a?.value || '').toString().toLowerCase().trim();
    try {
        // rsa-sha256 and ed25519-sha256 only, ARC has no rsa-sha1
        validateAlgorithm(algorithm, true);
    } catch {
        throw createError(`i=${chain.length} invalid seal algorithm`, 'invalid_arc_seal');
    }
    let { signAlgo } = splitAlgorithm(algorithm);

    let canonicalizedHeader = Buffer.concat(chunks);

    let publicKey: string;
    let queryDomain = sealKeyName(signatureHeader);
    try {
        // the key record's own h= and s= restrictions apply to ARC keys as well (RFC 6376
        // section 3.6.1), and every ARC signature uses sha256
        let res = await keyCache!.get('AS', queryDomain, opts?.minBitLength, { strict, hashAlgo: 'sha256' });

