        [`dkim._domainkey.${AUTHOR_DOMAIN}`]: { TXT: [[KEY_RECORD]] }
    };

    for (const hop of hops) {
        zone[hop.domain] = { TXT: [[`v=spf1 ip4:${hop.ip} -all`]] };
        zone[`arc._domainkey.${hop.domain}`] = { TXT: [[KEY_RECORD]] };
    }

    return zone;
};

